#!/bin/bash
# Prints the URN of every resource in the selected Pulumi stack, one per line, and nothing else.
#
# Workflows must not run `pulumi stack export` (or `pulumi stack --show-ids`) to find URNs: the
# export is the full state, and a random.RandomId resource's id is its raw generated bytes, so the
# runner would hold key material GitHub cannot mask (policy 795e72a6,
# .claude/rules/83-no-secret-readback-in-ci.md). `pulumi stack --show-urns` prints resource types,
# names and URNs, and stack outputs with secret values shown as [secret]. Only the URN lines are
# passed on; the rest of Pulumi's output is discarded and never printed.
#
# Run it from the Pulumi project directory (infra/) with the stack selected. Exits non-zero, with
# Pulumi's stderr, when the stack cannot be read, so callers can tell "no resources" from failure.
# Usage: bash scripts/deploy/pulumi-stack-urns.sh

set -euo pipefail

listing="$(pulumi stack --show-urns)"
# Pulumi prints each URN on its own line after the tree drawing: `│     URN: urn:pulumi:...`.
urns="$(printf '%s\n' "$listing" | sed -n 's/^.*URN: \(urn:pulumi:[^[:space:]]*\).*$/\1/p')"

# The header states how many resources the stack has. A listing whose URN count differs (or that
# has no header) is a format this script does not understand: fail rather than report too few.
expected="$(printf '%s\n' "$listing" | sed -n 's/^Current stack resources (\([0-9][0-9]*\)):.*$/\1/p' | head -n 1)"
found=0
if [ -n "$urns" ]; then
  found="$(printf '%s\n' "$urns" | wc -l | tr -d ' ')"
fi
if [ -z "$expected" ] || [ "$found" -ne "$expected" ]; then
  echo "pulumi-stack-urns: could not read the resource list (stated: ${expected:-none}, URNs found: $found)" >&2
  exit 1
fi
if [ "$found" -gt 0 ]; then
  printf '%s\n' "$urns"
fi
